const PT_VERBS = {
  save: 'guardar', 'save it': 'guardar', 'save them': 'guardar', 'save the membership': 'guardar a adesão', 'save single sign-on': 'guardar o início de sessão único',
  'save your profile': 'guardar o perfil', 'delete it': 'eliminar', 'add it': 'adicionar', 'check it': 'verificar', continue: 'continuar', recover: 'recuperar',
  'create the token': 'criar o token', 'add the stack': 'adicionar a stack',
  'create the administrator': 'criar o administrador', 'create the invite': 'criar o convite', 'create your account': 'criar a conta',
  'change your password': 'alterar a palavra-passe', 'make new codes': 'criar novos códigos', 'move them': 'mover', 'sign in': 'iniciar sessão', 'turn it on': 'ativar',
};
function tr(text) {
  if (PT_TEXT.has(text)) return PT_TEXT.get(text);
  for (const [re, to] of PT_PATTERNS) if (re.test(text)) return text.replace(re, to);
  return text;
}

const I18N_SKIP = 'script, style, code, textarea, .ap-code, .ap-data, .ap-kbd, .ap-avatar, [translate="no"]';
const I18N_ATTRS = ['placeholder', 'aria-label', 'title', 'data-label', 'alt'];
function translateNode(node) {
  if (node.nodeType === Node.TEXT_NODE) {
    const el = node.parentElement;
    if (!el || el.closest(I18N_SKIP)) return;
    const raw = node.nodeValue, text = raw.replace(/\s+/g, ' ').trim();
    if (!text) return;
    // Between two dates, "to" reads "a"; elsewhere, such as in a redirect, "para".
    const prev = node.previousSibling;
    // As a label, "Preview" is the noun, "Pré-visualização"; on a button, the verb, "Pré-visualizar".
    // In "Type <name> to confirm", "Type" is the verb, "Escreva"; elsewhere, the noun, "Tipo".
    const to = text === 'to' && prev && /^\d{4}-/.test(prev.textContent) ? 'a' : text === 'Preview' && el.classList.contains('ap-label') ? 'Pré-visualização' : text === 'Type' && el.classList.contains('ap-label') ? 'Escreva' : tr(text);
    if (to !== text) node.nodeValue = raw.replace(raw.trim(), to);
    return;
  }
  if (node.nodeType !== Node.ELEMENT_NODE || node.closest(I18N_SKIP)) return;
  for (const el of [node, ...node.querySelectorAll('*')]) {
    if (el.closest(I18N_SKIP)) continue;
    for (const a of I18N_ATTRS) {
      const v = el.getAttribute(a);
      if (v) { const to = tr(v); if (to !== v) el.setAttribute(a, to); }
    }
  }
  const walk = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
  for (let n = walk.nextNode(); n; n = walk.nextNode()) translateNode(n);
}

let i18nObserver = null;
function startTranslation() {
  beforeMeasure = translateNode;
  document.documentElement.lang = 'pt-PT';
  $('.ap').lang = 'pt-PT';
  translateNode(document.body);
  document.title = tr(document.title);
  i18nObserver = new MutationObserver(records => {
    for (const r of records) {
      if (r.type === 'characterData') translateNode(r.target);
      else if (r.type === 'attributes') { const v = r.target.getAttribute(r.attributeName); if (v) { const to = tr(v); if (to !== v) r.target.setAttribute(r.attributeName, to); } }
      else r.addedNodes.forEach(translateNode);
    }
    const title = tr(document.title);
    if (title !== document.title) document.title = title;
  });
  i18nObserver.observe(document.documentElement, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: I18N_ATTRS });
}
if (language === 'pt') startTranslation();
